"use client";
// update367: BANK SALARY PAYMENT SHEET.
//
// Every figure is the NET already generated by payroll — nothing is recomputed here, so an
// upload file can never disagree with the payslip someone was handed.
//
// Four choices I had to make and have not had answered. All four are easy to change; they
// are gathered here rather than scattered through the code:
//   1. CONTRACTORS ON ONE SHEET, one row each. Your bank uploads a file per sheet, and a
//      sheet per contractor would mean three uploads for one payment run.
//   2. ACCOUNT NUMBERS AS TEXT. A 14-digit number in a numeric cell becomes 5.02012E+13 and
//      the bank rejects the file. Text is the only safe form.
//   3. NARRATION "Sep-26 Salary" — 14 characters, alphanumeric, hyphen only. Most bank
//      formats cap at 30 and reject punctuation; this stays inside the strictest I know of.
//   4. CONTRACTOR AMOUNT IS NET of advances, per the Director's contractor flow: the
//      company owes the contractor, so the netting happens at the contractor.
import { supabase, isDemo } from "./supabase";
import { monthBounds } from "./payrollSettings";
import { getContractorNetting } from "./contractorAdvance";

export const PAY_COLS = ["Debit Account No", "Amount", "Beneficiary IFSC Code",
  "Beneficiary Account No", "Narration", "Beneficiary Name", "Beneficiary Bank Name"];

const clean = s => String(s || "").replace(/\s+/g, "").toUpperCase();
const money = n => +Number(n || 0).toFixed(2);

export function narrationFor(monthStr) {
  const [y, m] = monthStr.split("-").map(Number);
  const mon = new Date(y, m - 1, 1).toLocaleDateString("en-IN", { month: "short" });
  return `${mon}-${String(y).slice(2)} Salary`;
}

// a beneficiary is only payable with ALL THREE. Missing any one and the bank rejects the
// row, so they are pulled out to a follow-up list instead of silently shipping a bad file.
function bankable(r) {
  return !!(clean(r.account) && clean(r.ifsc) && String(r.bankName || "").trim());
}

export async function buildPaymentSheets(monthStr) {
  if (isDemo) return null;
  const { from } = monthBounds(monthStr);
  const narration = narrationFor(monthStr);

  const [{ data: settings }, { data: staffPay, error: e1 }, { data: wagePay, error: e2 }, contractors] =
    await Promise.all([
      supabase.from("app_settings").select("key, value").like("key", "company.debit%"),
      supabase.from("staff_payouts")
        .select("user_id, net, status, staff:user_id(full_name, bank_account_no, bank_ifsc, bank_name, payment_type, is_active)")
        .eq("pay_month", from),
      supabase.from("wage_payouts")
        .select("worker_id, site_id, net, status, workers!inner(full_name, bank_account_no, bank_ifsc, bank_name, payment_type, labour_type, contractor_id)")
        .eq("pay_month", from),
      getContractorNetting(monthStr).catch(() => []),
    ]);
  if (e1) throw new Error(e1.message);
  if (e2) throw new Error(e2.message);

  const cfg = {}; (settings || []).forEach(s => { cfg[s.key] = s.value; });
  const debit = cfg["company.debit_account_no"] || "";

  const row = (r) => ({
    debit, amount: money(r.amount), ifsc: clean(r.ifsc), account: clean(r.account),
    narration, name: r.name, bankName: String(r.bankName || "").trim(),
  });

  const staff = [], labour = [], union = [], missing = [];

  // ---- staff: one row per person, all sites combined (staff_payouts is already monthly) ----
  (staffPay || []).forEach(p => {
    const u = p.staff; if (!u) return;
    const amount = money(p.net);
    if (amount <= 0) return;
    const cand = { name: u.full_name, account: u.bank_account_no, ifsc: u.bank_ifsc,
                   bankName: u.bank_name, amount };
    const bucket = u.payment_type === "union" ? union : staff;
    if (bankable(cand)) bucket.push(row(cand));
    else missing.push({ ...cand, category: "Staff", payType: u.payment_type === "union" ? "Union" : "Direct",
                        why: whyMissing(cand) });
  });

  // ---- labour: a worker can have a payout per SITE, so sum them into one payment ----
  const byWorker = {};
  (wagePay || []).forEach(p => {
    const w = p.workers; if (!w) return;
    if (w.labour_type === "contractor" || w.payment_type === "contractor") return;   // paid via their contractor
    const k = p.worker_id;
    const b = byWorker[k] = byWorker[k] || { name: w.full_name, account: w.bank_account_no,
      ifsc: w.bank_ifsc, bankName: w.bank_name, payment_type: w.payment_type, amount: 0 };
    b.amount = money(b.amount + Number(p.net || 0));
  });
  Object.values(byWorker).forEach(b => {
    if (b.amount <= 0) return;
    const bucket = b.payment_type === "union" ? union : labour;
    if (bankable(b)) bucket.push(row(b));
    else missing.push({ ...b, category: "Labour", payType: b.payment_type === "union" ? "Union" : "Direct",
                        why: whyMissing(b) });
  });

  // ---- contractors: one row each, NET of outstanding advances ----
  const { data: cBank } = await supabase.from("contractors")
    .select("id, name, bank_account_no, bank_ifsc, bank_name");
  const bankBy = {}; (cBank || []).forEach(c => { bankBy[c.id] = c; });

  const contractor = [];
  (contractors || []).forEach(c => {
    if (c.netPayable <= 0) return;
    const b = bankBy[c.contractor_id] || {};
    const cand = { name: c.contractor_name, account: b.bank_account_no, ifsc: b.bank_ifsc,
                   bankName: b.bank_name, amount: c.netPayable };
    const r = { ...row(cand), narration: narration.replace("Salary", "Labour Contract"),
                wages: c.wages, netted: c.outstanding, workers: c.workers };
    if (bankable(cand)) contractor.push(r);
    else missing.push({ ...cand, category: "Contractor", payType: "Contractor", why: whyMissing(cand) });
  });

  const sum = a => money(a.reduce((n, x) => n + x.amount, 0));
  return {
    month: monthStr, narration, debit,
    debitMissing: !debit,
    staff, labour, union, contractor, missing,
    totals: { staff: sum(staff), labour: sum(labour), union: sum(union), contractor: sum(contractor),
              missing: sum(missing),
              all: money(sum(staff) + sum(labour) + sum(union) + sum(contractor)) },
  };
}

function whyMissing(r) {
  const gaps = [];
  if (!clean(r.account)) gaps.push("account no");
  if (!clean(r.ifsc)) gaps.push("IFSC");
  if (!String(r.bankName || "").trim()) gaps.push("bank name");
  return gaps.join(" + ");
}
